        mismatched.append(name + " (missing)")
        continue
    if path.read_text(encoding="utf-8") != content:
        mismatched.append(name + " (changed)")
if mismatched:
    print("workspace files changed: " + ", ".join(mismatched))
    sys.exit(1)
